--
-- CO-OP - building vanilla objects: the two hooks every generated build recipe names.
--
-- The recipes themselves are scripts/entity_coop_buildables.txt, generated by
-- tools/buildables/generate.py. Each one is an isProp entity, so ISBuildIsoEntity:setInfo
-- places it through ISMoveableSpriteProps:placeMoveableInternal - the same code that
-- puts a picked-up moveable back down - and a built oven is an IsoStove, a lamp an
-- IsoLightSwitch, a window an IsoWindow. Nothing here creates objects.
--
-- Both hooks are global functions on purpose: OnAddToMenu and OnIsValid are looked up
-- with a raw get on the global table (see COOP_Well.lua), so "COOPBuild.isValid" would
-- never be found.
--

require "COOP_Common"

COOPBuild = COOPBuild or {}

-- canPlaceMoveableInternal asks an IsoPlayer for the vanilla *place* skill and tool
-- (a hammer for furniture, Electrical for appliances). The recipe has already charged
-- its own skills and tools, so the moveable rules are asked as nobody in particular.
-- Vanilla's own stackable check passes a string the same way ("bogus").
COOPBuild.NOT_A_PLAYER = "COOPBuild"

-- true while windows and frames are being checked in game; logs to console.txt
COOPBuild.debug = true

function COOPBuild.isEnabled()
    return COOP.featureEnabled(COOP.F_BUILD)
end

function COOP_BuildInMenu(_params)
    return COOPBuild.isEnabled()
end

-- OnIsValid, once per tile of the object, before vanilla's own per-square checks.
-- Those checks are written for thumpables: they want a free floor under everything, so
-- a lamp could never go on a table or a phone on a desk. The moveable rules know where
-- each kind of object may stand - on a table, against a wall, in a window frame, not
-- under a high shelf - so they decide, and when they say yes vanilla's collision test
-- is switched off for that square. A multi-tile object keeps it: canPlaceMoveableInternal
-- looks at one square only, and the collision test is what stops a couch being built
-- through a wall.
--
-- Windows are left to vanilla: the recipe says needWindowFrame, and ISBuildIsoEntity
-- then wants an empty frame of that facing on the square and no window in it, which is
-- the whole rule. The moveables' own window test looks for IsoFlagType.WindowW/N on the
-- square, and in the first in-game test no window could be built anywhere.

-- debug: one line per sprite each time its answer changes, not one per frame
local lastAnswer = {}

local function answer(_spriteName, _square, _result, _why)
    if COOPBuild.debug and lastAnswer[_spriteName] ~= _why then
        lastAnswer[_spriteName] = _why
        COOP.log(string.format("build check %s at %d,%d,%d: %s (%s)", _spriteName,
            _square:getX(), _square:getY(), _square:getZ(), tostring(_result), _why))
    end
    return _result
end

function COOP_BuildIsValid(_params)
    if not COOPBuild.isEnabled() then return false end
    local square = _params.square
    local spriteName = _params.tileInfo and _params.tileInfo:getSpriteName()
    if square == nil or spriteName == nil then return true end

    local ok, can, multi, kind = pcall(function()
        local props = ISMoveableSpriteProps.new(getSprite(spriteName))
        if not props.isMoveable then return nil, false, "not moveable" end
        if props.type == "Window" then return nil, false, "Window" end
        return props:canPlaceMoveableInternal(COOPBuild.NOT_A_PLAYER, square, nil, false),
            props.isMultiSprite, props.type
    end)
    if not ok then
        -- fail open: vanilla's own checks still run after this
        return answer(spriteName, square, true, "check threw: " .. tostring(can))
    end
    if can == nil then return answer(spriteName, square, true, "left to vanilla: " .. tostring(kind)) end
    if not can then return answer(spriteName, square, false, "moveable rules say no: " .. tostring(kind)) end
    if not multi then _params.testCollisions = false end
    return answer(spriteName, square, true, "moveable rules say yes: " .. tostring(kind))
end

-- Debug only: vanilla's verdict on each tile, after our hook and its own checks, so a
-- red cursor in the log says which side refused. Logged when a sprite's answer changes.
-- Nothing else in the mod wraps isValidPerSquare.
local lastVerdict = {}
local wrapped = nil

local function wrapVerdict()
    if not COOPBuild.debug or ISBuildIsoEntity == nil then return end
    if wrapped ~= nil and ISBuildIsoEntity.isValidPerSquare == wrapped then return end
    local original = ISBuildIsoEntity.isValidPerSquare
    wrapped = function(self, square, tileInfo, ...)
        local result = original(self, square, tileInfo, ...)
        local name = tileInfo and tileInfo:getSpriteName()
        if name and lastVerdict[name] ~= result then
            lastVerdict[name] = result
            COOP.log(string.format("build verdict %s at %d,%d,%d: %s (north=%s needWindowFrame=%s previousStages=%d)",
                name, square:getX(), square:getY(), square:getZ(), tostring(result),
                tostring(self.north), tostring(self.needWindowFrame),
                self.previousStages and self.previousStages:size() or -1))
        end
        return result
    end
    ISBuildIsoEntity.isValidPerSquare = wrapped
end

Events.OnGameStart.Add(wrapVerdict)
